import json

# Check: what's the finish_reason distribution for GLM requests?
with open('/root/.nanobot/request_logs/2026-05-11.jsonl') as f:
    lines = f.readlines()

finish_dist = {}
tool_calls_samples = []
for line in lines:
    try:
        rec = json.loads(line.strip().rstrip(','))
        model = rec.get('model','')
        if 'glm' in model.lower():
            fr = rec.get('finish_reason','') or 'empty'
            finish_dist[fr] = finish_dist.get(fr, 0) + 1
            if fr == 'tool_calls' and len(tool_calls_samples) < 3:
                tool_calls_samples.append(rec)
    except:
        pass

print("=== GLM Finish Reason Distribution ===")
for k,v in sorted(finish_dist.items(), key=lambda x:-x[1]):
    print(f"  {k}: {v}")

print("\n=== Sample tool_calls requests ===")
for s in tool_calls_samples:
    print(f"  ts={s.get('ts','')} | chars={s.get('total_chars',0):,} | msgs={s.get('msg_count',0)} | reply_len={s.get('reply_len',0)}")
