    try:
        rec = json.loads(line.strip().rstrip(','))
        model = rec.get('model','')
        if 'glm' in model.lower():
            models.add(model)
    except:
        pass
print(f"\n=== Unique GLM model names ===")
for m in sorted(models):
    print(f"  {m}")
