import json

# Check: which requests use GLM 5.1 specifically vs GLM 5 turbo?
with open('/root/.nanobot/request_logs/2026-05-11.jsonl') as f:
    lines = f.readlines()

glm51 = []
glm5turbo = []
for line in lines:
    try:
        rec = json.loads(line.strip().rstrip(','))
        model = rec.get('model','')
        if 'glm-5.1' in model:
            glm51.append(rec)
        elif 'glm-5-turbo' in model:
            glm5turbo.append(rec)
    except:
        pass

print(f"=== GLM 5.1 requests: {len(glm51)} ===")
if glm51:
    finish_dist = {}
    for r in glm51:
        fr = r.get('finish_reason','') or 'empty'
        finish_dist[fr] = finish_dist.get(fr, 0) + 1
    print(f"  finish: {finish_dist}")
    # Show agent distribution
    agents = {}
    for r in glm51:
        a = r.get('agent','?')
        agents[a] = agents.get(a, 0) + 1
    print(f"  agents: {agents}")
    # Sample
    for s in glm51[:3]:
        print(f"  [{s.get('ts','')}] agent={s.get('agent','?')} | chars={s.get('total_chars',0):,} | msgs={s.get('msg_count',0)} | finish='{s.get('finish_reason','')}'")

print(f"\n=== GLM 5 Turbo requests: {len(glm5turbo)} ===")
if glm5turbo:
    finish_dist = {}
    for r in glm5turbo:
        fr = r.get('finish_reason','') or 'empty'
        finish_dist[fr] = finish_dist.get(fr, 0) + 1
    print(f"  finish: {finish_dist}")
    agents = {}
    for r in glm5turbo:
        a = r.get('agent','?')
        agents[a] = agents.get(a, 0) + 1
    print(f"  agents: {agents}")
    for s in glm5turbo[:3]:
        print(f"  [{s.get('ts','')}] agent={s.get('agent','?')} | chars={s.get('total_chars',0):,} | msgs={s.get('msg_count',0)} | finish='{s.get('finish_reason','')}'")
